; ============================================== sub step ====

step:
; ---- if ( prompting ) {
        mov     al, [prompting]
        test    al, al
        jz      .L1006
; ---- promptKey( k )
        mov     ax, [step__k]
        mov     [promptKey__k], ax
        call    promptKey
; ---- return
        ret
.L1006:
; ---- message = 0
        mov     word [message], 0
; ---- selecting = false
        mov     byte [selecting], 0
; ---- if ( k >= keyShift ) {
        mov     ax, [step__k]
        cmp     ax, 512
        jb      .L1009                      ; unsigned >=
; ---- selecting = true
        mov     byte [selecting], 1
; ---- k = keyExt + ( k - keyShift )
        mov     ax, 256
        push    ax                          ; save lhs: rhs is not a leaf
        mov     ax, [step__k]
        sub     ax, 512
        mov     bx, ax
        pop     ax
        add     ax, bx
        mov     [step__k], ax
.L1009:
; ---- if ( k == keyEsc ) {
        mov     ax, [step__k]
        cmp     ax, 27
        jne     .L1012                      ; unsigned ==
; ---- viewUnmark()
        call    viewUnmark
; ---- return
        ret
.L1012:
; ---- had = pending
        mov     ax, [pending]
        mov     [step__had], ax
; ---- a = keyAction( k )
        mov     ax, [step__k]
        mov     [keyAction__k], ax
        call    keyAction
        mov     al, [keyAction__ret]
        xor     ah, ah                      ; u8 -> u16
        mov     [step__a], al               ; narrowed to u8
; ---- if ( a == actNone && had == 0 && keyIsPrefix( k ) ) {
        test    al, al
        jne     .L1015                      ; unsigned ==
        mov     ax, [step__had]
        test    ax, ax
        jne     .L1015                      ; unsigned ==
        mov     ax, [step__k]
        mov     [keyIsPrefix__k], ax
        call    keyIsPrefix
        mov     al, [keyIsPrefix__ret]
        xor     ah, ah                      ; bool -> u16
        test    ax, ax
        jz      .L1015
; ---- pending = k
        mov     ax, [step__k]
        mov     [pending], ax
; ---- return
        ret
.L1015:
; ---- pending = 0
        mov     word [pending], 0
; ---- if ( k == keyQuit ) {
        mov     ax, [step__k]
        cmp     ax, 17
        jne     .L1020                      ; unsigned ==
; ---- running = false
        mov     byte [running], 0
; ---- return
        ret
.L1020:
; ---- if ( a == actNone && had == 0 && k >= 32 && k < 127 ) a = actInsert
        mov     al, [step__a]
        test    al, al
        jne     .L1023                      ; unsigned ==
        mov     ax, [step__had]
        test    ax, ax
        jne     .L1023                      ; unsigned ==
        mov     ax, [step__k]
        cmp     ax, 32
        jb      .L1023                      ; unsigned >=
        mov     ax, [step__k]
        cmp     ax, 127
        jae     .L1023                      ; unsigned <
        mov     byte [step__a], 1
.L1023:
; ---- apply( a, k )
        mov     al, [step__a]
        mov     [apply__a], al              ; u8 -> u8, no widening
        mov     ax, [step__k]
        mov     [apply__k], ax
        call    apply
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int10:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x10
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pushf
        pop     ax
        and     al, 1                       ; carry is bit 0
        mov     [_cf], al
        pop     es
        ret

int16:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x16
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pushf
        pop     ax
        and     al, 1                       ; carry is bit 0
        mov     [_cf], al
        pop     es
        ret

int21:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pushf
        pop     ax
        and     al, 1                       ; carry is bit 0
        mov     [_cf], al
        pop     es
        ret

